theorem real_powers_positive_dimension_set (exponent : ℝ) (exponent_gt_one : 1 < exponent) :
    0 < dimH {point : ℝ × ℝ | point.1 ∈ cantorSet (1/3) ∧
      point.2 ∈ cantorSet (1/3) ∧ point.1 ^ exponent + point.2 ^ exponent = 1}

def HasPositiveSobolevDensity (measure : Measure ℝ) : Prop :=
  HasL2Density measure ∧ ∃ order : ℝ, 0 < order ∧
    Integrable (fun frequency : ℝ => (1 + frequency ^ 2) ^ order * ‖charFun measure frequency‖ ^ 2)

theorem irrational_parameters {exponent lower upper : ℝ}
    (hirrational : Irrational exponent) (hexponent : 1 < exponent)
    (hlower : (1 / 4 : ℝ) ≤ lower) (hordered : lower < upper)
    (hupper : upper ≤ 1 / 2) :
    0 < volume {ratio : ℝ | ratio ∈ Ioo lower upper ∧
      0 < dimH (intersection exponent ratio)}

theorem irrational_onset {exponent : ℝ}
    (hirrational : Irrational exponent) (hexponent : 1 < exponent) :
    firstTransition exponent = 1 / 4

theorem circle_positive_measure (epsilon : ℝ) (epsilon_positive : 0 < epsilon) :
    0 < volume {ratio : ℝ | ratio ∈ Set.Ioo onset (onset + epsilon) ∧
      0 < dimH (intersection 2 ratio)}

